<?php
function nstBankReportData($db,$from,$to,$account=0){
 if(!nstPayrollDate($from)||!nstPayrollDate($to)||$from>$to)throw new InvalidArgumentException('Seleccione un rango de fechas válido.');
 $users=[];foreach($db->query('SELECT Usuario,NombreUsuario FROM Seg_Usuario')->fetchAll(PDO::FETCH_ASSOC) as $u)$users[strtolower(trim($u['Usuario']))]=trim((string)$u['NombreUsuario']);
 $q=$db->prepare('SELECT c.IdCuenta,c.Cuenta,c.Anulado,b.FechaInicio FechaControl,b.SaldoInicial BaseControl,b.UsuarioReg UsuarioApertura,b.UsuarioMod UsuarioEditaApertura,b.Version VersionSaldo FROM Cb_Cuenta c LEFT JOIN Cb_SaldoBanco b ON b.IdCuenta=c.IdCuenta WHERE c.IdCuenta<>1 AND (?=0 OR c.IdCuenta=?) ORDER BY c.Cuenta');$q->execute([$account,$account]);$accounts=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT cb.IdCajaBanco,cb.IdCuenta,cb.FechaDoc,cb.Concepto,cb.Importe,cb.Anulado,cb.UsuarioReg,t.Tipo,t.TipoCajaBanco,pr.Proveedor,cl.Cliente,pg.Tipo TipoPlanilla,pg.Referencia,pg.Anulado PagoAnulado,e.Empleado FROM Cb_CajaBanco cb JOIN Cb_TipoCajaBanco t ON t.IdTipoCajaBanco=cb.IdTipoCajaBanco LEFT JOIN Lo_Proveedor pr ON pr.IdProveedor=cb.IdProveedor LEFT JOIN Ve_DocVentaCliente cl ON cl.IdCliente=cb.IdCliente LEFT JOIN Rhu_PlanillaPago pg ON pg.IdCajaBanco=cb.IdCajaBanco LEFT JOIN Rhu_PlanillaPeriodo pp ON pp.IdPlanilla=pg.IdPlanilla LEFT JOIN Rhu_Empleado e ON e.IdEmpleado=pp.IdEmpleado WHERE cb.IdCuenta<>1 AND (?=0 OR cb.IdCuenta=?) AND cb.FechaDoc<? ORDER BY cb.FechaDoc,cb.IdCajaBanco");
 $end=(new DateTime($to))->modify('+1 day')->format('Y-m-d');$q->execute([$account,$account,$end]);$groups=[];foreach($accounts as $a){$active=$a['FechaControl']&&$a['FechaControl']<=$to;$base=$active?(float)$a['BaseControl']:0;$groups[$a['IdCuenta']]=array_merge($a,['ControlActivo'=>$active,'Inicial'=>$base,'Ingresos'=>0,'Salidas'=>0,'Saldo'=>$base,'Personal'=>0,'Movimientos'=>[],'Usuarios'=>[]]);}
 foreach($q->fetchAll(PDO::FETCH_ASSOC) as $m){if(!isset($groups[$m['IdCuenta']]))continue;$g=&$groups[$m['IdCuenta']];if($g['ControlActivo']&&substr($m['FechaDoc'],0,10)<$g['FechaControl']){unset($g);continue;}$void=(int)$m['Anulado']||(int)$m['PagoAnulado'];$amount=round((float)$m['Importe'],2);$direction=(int)$m['Tipo']===0?1:-1;$value=$void?0:$direction*$amount;
 if(substr($m['FechaDoc'],0,10)<$from){$g['Inicial']=round($g['Inicial']+$value,2);$g['Saldo']=$g['Inicial'];unset($g);continue;}
 $username=trim((string)$m['UsuarioReg']);$name=$users[strtolower($username)]??'';
 $m['UsuarioNombre']=$name;$m['RegistradoPor']=$username!==''?($name!==''&&strcasecmp($name,$username)!==0?$username.' ('.$name.')':$username):'Sin usuario registrado';
 if(!in_array($m['RegistradoPor'],$g['Usuarios'],true))$g['Usuarios'][]=$m['RegistradoPor'];
 $m['Anulado']=$void?1:0;$m['Ingreso']=!$void&&$direction===1?$amount:0;$m['Salida']=!$void&&$direction===-1?$amount:0;$m['Beneficiario']=$m['Empleado']?:($m['Proveedor']?:($m['Cliente']?:''));$m['Operacion']=$m['TipoPlanilla']?('PLANILLA '.$m['TipoPlanilla']):$m['TipoCajaBanco'];$g['Ingresos']=round($g['Ingresos']+$m['Ingreso'],2);$g['Salidas']=round($g['Salidas']+$m['Salida'],2);$g['Saldo']=round($g['Saldo']+$value,2);if($m['TipoPlanilla'])$g['Personal']=round($g['Personal']+$m['Salida'],2);$m['Saldo']=$g['Saldo'];$g['Movimientos'][]=$m;unset($g);
 }
 return ['Desde'=>$from,'Hasta'=>$to,'Cuentas'=>array_values($groups),'empresa'=>$db->query('SELECT RAZONSOCIAL,RUC,DIRECCION FROM Gen_Empresa LIMIT 1')->fetch(PDO::FETCH_ASSOC)];
}
function nstBankReportHtml($data,$user){
 $e=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$money=function($v){return number_format((float)$v,2);};$company=$data['empresa'];$summary='';$detail='';$totals=[0,0,0,0];
 foreach($data['Cuentas'] as $g){$summary.='<tr><td>'.$e($g['Cuenta']).'</td><td class="num">'.$money($g['Inicial']).'</td><td class="num">'.$money($g['Ingresos']).'</td><td class="num">'.$money($g['Salidas']).'</td><td class="num">'.$money($g['Personal']).'</td><td class="num"><b>'.$money($g['Saldo']).'</b></td></tr>';foreach(['Inicial','Ingresos','Salidas','Saldo'] as $i=>$key)$totals[$i]+=$g[$key];
 $rows='';foreach($g['Movimientos'] as $m)$rows.='<tr'.($m['Anulado']?' class="void"':'').'><td>'.$e($m['FechaDoc']).'<br>#'.$e($m['IdCajaBanco']).'</td><td><b>'.$e($m['Operacion']).'</b>'.($m['Anulado']?'<br><b>ANULADO</b>':'').'<br>'.$e($m['Beneficiario']).'<br>'.$e($m['Concepto']).($m['Referencia']?'<br>Ref: '.$e($m['Referencia']):'').'</td><td>'.$e($m['RegistradoPor']).'</td><td class="num">'.$money($m['Ingreso']).'</td><td class="num">'.$money($m['Salida']).'</td><td class="num">'.$money($m['Saldo']).'</td></tr>';
 $detail.='<section class="account"><h2>'.$e($g['Cuenta']).'</h2><p>'.($g['ControlActivo']?'Control desde '.$e($g['FechaControl']).' · Saldo inicial configurado S/ '.$money($g['BaseControl']).' · Registrado por '.$e($g['UsuarioApertura']).($g['UsuarioEditaApertura']?' · Editado por '.$e($g['UsuarioEditaApertura']):''):'Sin saldo inicial configurado para este rango; saldo calculado desde el historial registrado.').'</p><div class="balance">Saldo registrado al '.$e($data['Hasta']).': <b>S/ '.$money($g['Saldo']).'</b></div><p>Registrado por: '.$e(implode(', ',$g['Usuarios']) ?: 'Sin movimientos en el rango').'</p><p>Saldo inicial registrado: <b>S/ '.$money($g['Inicial']).'</b> &nbsp; | &nbsp; Ingresos: <b>S/ '.$money($g['Ingresos']).'</b> &nbsp; | &nbsp; Salidas: <b>S/ '.$money($g['Salidas']).'</b> &nbsp; | &nbsp; Saldo final registrado: <b>S/ '.$money($g['Saldo']).'</b></p><table><thead><tr><th width="13%">Fecha / ID</th><th width="37%">Operación / beneficiario / detalle</th><th width="14%">Registrado por</th><th width="12%">Ingreso S/</th><th width="12%">Salida S/</th><th width="12%">Saldo S/</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="6">Sin movimientos en el rango seleccionado.</td></tr>').'</tbody><tfoot><tr><td colspan="3"><b>SUMATORIA '.$e($g['Cuenta']).'</b></td><td class="num"><b>'.$money($g['Ingresos']).'</b></td><td class="num"><b>'.$money($g['Salidas']).'</b></td><td class="num"><b>'.$money($g['Saldo']).'</b></td></tr></tfoot></table></section>';
 }
 $personalTotal=array_sum(array_column($data['Cuentas'],'Personal'));
 $summary.='<tr><td><b>TOTAL BANCOS</b></td><td class="num"><b>'.$money($totals[0]).'</b></td><td class="num"><b>'.$money($totals[1]).'</b></td><td class="num"><b>'.$money($totals[2]).'</b></td><td class="num"><b>'.$money($personalTotal).'</b></td><td class="num"><b>'.$money($totals[3]).'</b></td></tr>';
 return '<html><head><meta charset="UTF-8"><style>@page{margin:24px 24px 38px}body{font-family:DejaVu Sans,sans-serif;color:#173e52;font-size:10px;line-height:1.15}p{margin:5px 0}h1{font-size:19px;margin:7px 0}h2{font-size:14px;margin:12px 0 5px;page-break-after:avoid;color:#087f8c}.brand{font-weight:bold;color:#078b98;font-size:9px}.note{background:#edf6f9;padding:7px;line-height:1.2;margin:8px 0;font-size:9px}table{width:100%;border-collapse:collapse;table-layout:fixed}th{background:#153f54;color:white;text-align:left;padding:5px 4px}td{padding:5px 4px;border-bottom:1px solid #dce8ee;vertical-align:top;word-wrap:break-word}tr:nth-child(even){background:#f2f7fa}thead{display:table-header-group}tr{page-break-inside:avoid}.num{text-align:right;white-space:nowrap}.account{margin-top:12px;page-break-before:auto}.balance{background:#e6f5f1;padding:7px;font-size:12px;color:#08776e}tfoot{display:table-row-group}tfoot td{background:#eaf3f7;border-top:2px solid #153f54}.void{color:#a06868;background:#fff3f3}.foot{position:fixed;bottom:-24px;font-size:8px;color:#6a8999}</style></head><body><div class="brand">'.$e($company['RAZONSOCIAL']).' · RUC '.$e($company['RUC']).'</div><h1>REPORTE CONSOLIDADO DE BANCOS</h1><p>Del '.$e($data['Desde']).' al '.$e($data['Hasta']).' · Moneda: soles (PEN)</p><p>Generado por: '.$e($user).' · '.(new DateTime('now',new DateTimeZone('America/Lima')))->format('d/m/Y H:i').'</p><div class="note">Caja Principal excluida. Saldos del sistema: saldo inicial + ingresos − salidas; no constituyen conciliación bancaria. Personal está incluido en las salidas. Los anulados no afectan totales. Con saldo inicial configurado, el cálculo comienza en la fecha de control de cada cuenta.</div><h2>Consolidado por cuenta</h2><table><thead><tr><th>Cuenta</th><th>Inicial S/</th><th>Ingresos S/</th><th>Salidas S/</th><th>Personal S/ *</th><th>Saldo al cierre S/</th></tr></thead><tbody>'.$summary.'</tbody></table><p>* Personal es un desglose de las salidas; no se suma nuevamente.</p>'.$detail.'<div class="foot">Reporte de bancos · '.$e($data['Desde']).' al '.$e($data['Hasta']).'</div></body></html>';
}
return function($app){
 $handler=function($q,$r,$pdf=false){if(session_status()!==PHP_SESSION_ACTIVE)session_start();$user=$_SESSION['user']??'';session_write_close();if(!$user)return $r->withJson(['error'=>'Inicie sesión nuevamente.'],401);if(strtolower(trim((string)$user))!=='superadmin')return $r->withJson(['error'=>'Reporte disponible solo para superadmin.'],403);try{$data=nstBankReportData($this->db,$q->getParam('desde')?:date('Y-m-01'),$q->getParam('hasta')?:date('Y-m-d'),(int)$q->getParam('cuenta'));if(!$pdf)return $r->withJson($data);
 $base=__DIR__.'/sunat/plugins/dompdf';ob_start();try{require_once $base.'/lib/html5lib/Parser.php';require_once $base.'/lib/php-font-lib/src/FontLib/Autoloader.php';require_once $base.'/lib/php-svg-lib/src/autoload.php';require_once $base.'/src/Autoloader.php';\Dompdf\Autoloader::register();$d=new \Dompdf\Dompdf();$d->set_paper('A4','portrait');$d->load_html(nstBankReportHtml($data,$user));$d->render();$d->get_canvas()->page_text(525,815,'{PAGE_NUM} / {PAGE_COUNT}',null,8);$bytes=$d->output();}finally{ob_end_clean();}$r->getBody()->write($bytes);return $r->withHeader('Content-Type','application/pdf')->withHeader('Content-Disposition','inline; filename="Reporte_Bancos_'.$data['Desde'].'_'.$data['Hasta'].'.pdf"')->withHeader('Cache-Control','private, no-store');
 }catch(InvalidArgumentException $e){return $r->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){error_log('[NST-BANCOS] '.$e->getMessage());return $r->withJson(['error'=>'No se pudo generar el reporte.'],500);}};
 $app->get('/bancos/reporte',function($q,$r)use($handler){return $handler->bindTo($this)($q,$r);});$app->get('/bancos/reporte/pdf',function($q,$r)use($handler){return $handler->bindTo($this)($q,$r,true);});
};
